}
function cmpV(a, b) {
  const x = parseV(a), y = parseV(b);
  for (const k of ["major", "minor", "patch"]) if (x[k] !== y[k]) return x[k] < y[k] ? -1 : 1;
  if (!x.pre.length && !y.pre.length) return 0;
  if (!x.pre.length) return 1;
  if (!y.pre.length) return -1;
  const n = Math.max(x.pre.length, y.pre.length);
  for (let i = 0; i < n; i++) {
    if (i >= x.pre.length) return -1;
    if (i >= y.pre.length) return 1;
    const p = x.pre[i], q = y.pre[i];
    if (p === q) continue;
    const pn = /^\d+$/.test(p), qn = /^\d+$/.test(q);
    if (pn && qn) return +p < +q ? -1 : 1;
    if (pn) return -1;
    if (qn) return 1;
    return p < q ? -1 : 1;
  }
  return 0;
}
// Готово: поддерживает точную версию, ^, ~, >=, >, <=, <, * и «И» через пробел (без предрелизов)
function satisfies(version, range) {
  const v = parseV(version);
  if (!v || v.pre.length) return false;
  return range.trim().split(/\s+/).every((c) => {
    if (c === "*" || c === "") return true;
    const m = /^(\^|~|>=|<=|>|<|=)?(\d+\.\d+\.\d+)$/.exec(c);
    const op = m[1] || "=", t = parseV(m[2]);
    const r = cmpV(version, m[2]);
    if (op === "^") {
