      return r >= 0 && cmpV(version, up) < 0;
    }
    if (op === "~") return r >= 0 && cmpV(version, `${t.major}.${t.minor + 1}.0`) < 0;
    return op === ">=" ? r >= 0 : op === "<=" ? r <= 0 : op === ">" ? r > 0 : op === "<" ? r < 0 : r === 0;
