  return range.trim().split(/\s+/).every((c) => {
    if (c === "*" || c === "") return true;
    const m = /^(\^|~|>=|<=|>|<|=)?(\d+\.\d+\.\d+)$/.exec(c);
    const op = m[1] || "=", t = parseV(m[2]);
    const r = cmpV(version, m[2]);
    if (op === "^") {
      const up = t.major > 0 ? `${t.major + 1}.0.0` : t.minor > 0 ? `0.${t.minor + 1}.0` : `0.0.${t.patch + 1}`;
      return r >= 0 && cmpV(version, up) < 0;
    }
